/**
 * get_query_reference tool — full reference for a root GraphQL query.
 */
import { z } from 'zod';
export const getQueryReferenceSchema = z.object({
    query_name: z.string().max(200).describe('Name of a root GraphQL query (e.g. "token", "transactions", "block")'),
});
function formatQuery(q, schema) {
    const args = q.args.map(a => {
        const req = a.required ? ' (required)' : '';
        const def = a.default ? ` = ${a.default}` : '';
        return `  - \`${a.name}\`: \`${a.type}\`${req}${def}${a.description ? ` — ${a.description}` : ''}`;
    }).join('\n');
    // Find the filter input type if one of the args references it
    const filterArg = q.args.find(a => a.type.toLowerCase().includes('filter'));
    let filterInfo = '';
    if (filterArg) {
        const filterTypeName = filterArg.type.replace(/[!\[\]]/g, '');
        const filterType = schema.inputTypes.find(t => t.name === filterTypeName);
        if (filterType) {
            const fields = filterType.fields.map(f => `    - \`${f.name}\`: \`${f.type}\`${f.description ? ` — ${f.description}` : ''}`).join('\n');
            filterInfo = `\n\n**Filter type** (\`${filterTypeName}\`):\n${fields}`;
        }
    }
    const returnStr = q.isList ? `[${q.returnType}]` : q.returnType;
    return `# ${q.name}\n\n${q.description}\n\n**Returns:** \`${returnStr}\`${q.returnRequired ? ' (non-null)' : ''}\n\n**Arguments:**\n${args}${filterInfo}`;
}
export function handleGetQueryReference(input, schema) {
    if (!schema) {
        return 'Schema data not available. Data files may be missing — try reinstalling the package.';
    }
    const name = input.query_name.toLowerCase().trim();
    const query = schema.rootQueries.find(q => q.name.toLowerCase() === name);
    if (!query) {
        const available = schema.rootQueries.map(q => q.name).join(', ');
        return `Query "${input.query_name}" not found. Available root queries: ${available}`;
    }
    return formatQuery(query, schema);
}
